# (download/*.epub): *parola* = parola in ambra. `python carousel.py` rende le slide,
# `python carousel.py --calendar` aggiunge le voci a ../calendar.json.
CTA = "Puntata 1 gratis in PDF ed EPUB, senza iscrizione: link in bio."
BUG, OBL = "Il Bug della Trasparenza", "L’Economia dell’Oblio"
Q = lambda text, **kw: dict(k="quote", text=text, **kw)
END = dict(k="cta")


def single(id, when, book, seg, slide, caption, tags, alt, theme=None):
    return dict(id=id, when=when, book=book, seg=seg, slides=[slide], caption=caption, tags=tags, alt=alt, theme=theme)


